  ('t-26388', 2, 'SakugaThreadZero', 'av-zeroframe', 'Database Contributor', null, false, 'Solid opener. Animation is steady rather than flashy, which is honestly what you want for a two-cour show. Let''s see how it holds up by summer.', '2013-04-04T16:44:00Z', 'JST', null, null, false, 'reconstructed'),
  ('t-26388', 3, 'FinalBossu', 'av-finalbossu', 'Anime Addict', null, false, 'Thursday nights are booked until September now. Sawano insert tracks hit every single time.', '2013-04-05T01:20:00Z', 'JST', null, null, false, 'reconstructed'),
